<?php
/** Proof — the life of a bill (spec "Proof", 2): draft with two lines and the document; a duplicate vendor reference; the approval by the Controller (gross posting); the lines fixed; void; copy; the lists. */
require __DIR__ . '/lib.php';
$bea = as_member(27); $carl = as_member(28); $vera = as_member(26);
$fx = ap_fixture();
$H = mk_vendor('SMOKE Hosting Co', ['terms_days' => '30', 'expense_account' => account_id('6200'), 'currency' => 'USD']);
$N = mk_vendor('SMOKE Other Vendor');
$pdf = tmp_pdf('SMOKE-bill.pdf');
echo "1. Draft with two lines and the document\n";
$since = last_activity_id();
$lines = json_encode([['description' => 'Server rental', 'quantity' => '1', 'unit_price' => '240.00', 'expense_account' => '6200', 'tax_rate' => (string) $fx['tax']], ['description' => 'Backup', 'quantity' => '2', 'unit_price' => '50.00', 'expense_account' => '6100']]);
[$c, $b, $raw] = act_upload($bea, '/bills/save.php', ['vendor' => $H, 'vendor_ref' => 'H-2026-04', 'bill_date' => '2026-06-01', 'memo' => 'SMOKE hosting', 'lines' => $lines], ['document' => [$pdf, 'invoice.pdf']]);
$B1 = (int) ($b['record_id'] ?? 0);
ok($c === 200 && $B1 > 0 && ($b['location'] ?? '') === '/bills/' . $B1 . '?notice=saved' && ($b['has_document'] ?? false) === true && preg_match('/^BILL-\d{6}$/', (string) ($b['number'] ?? '')) === 1, "bill_draft: 200, record_id $B1, a number at creation (" . ($b['number'] ?? '?') . "), has_document true");
$row = bill_row($B1);
ok($row['status'] === 'draft' && $row['vendor_ref'] === 'H-2026-04' && $row['bill_date'] === '2026-06-01' && $row['due_date'] === '2026-07-01' && $row['currency'] === 'USD' && $row['source'] === 'manual' && $row['subtotal'] === '340.00' && $row['tax_total'] === '19.80' && $row['total'] === '359.80', 'a draft: due 30 days on from the vendor\'s terms, USD, 340.00 + 19.80 tax = 359.80');
$ls = q('SELECT description, line_total, expense_account_id FROM bill_lines WHERE bill_id = :b ORDER BY sort_order', ['b' => $B1]);
ok(count($ls) === 2 && $ls[0]['line_total'] === '259.80' && (int) $ls[0]['expense_account_id'] === account_id('6200') && $ls[1]['line_total'] === '100.00' && (int) $ls[1]['expense_account_id'] === account_id('6100'), 'the lines: 259.80 to 6200 (tax included), 100.00 to 6100');
ok((int) one("SELECT count(*) FROM attachments WHERE record_type = 'bill' AND record_id = :b", ['b' => $B1]) === 1 && (int) one('SELECT count(*) FROM mcp_bills WHERE bill_id = :b AND has_attachment', ['b' => $B1]) >= 0, 'the document is attached on the same post');
pdo()->exec("SELECT set_config('app.member_id', '27', false)");
ok((bool) one('SELECT has_attachment FROM mcp_bills WHERE bill_id = :b', ['b' => $B1]) === true, 'the view says has_attachment');
$l = activity('bill.draft', $since)[0]; $a = json_decode((string) $l['after'], true);
ok((int) $l['vendor_id'] === $H && $a['has_document'] === true && $a['amount'] === '359.80' && $a['lines'] === 2 && $a['vendor_ref'] === 'H-2026-04' && count(activity('attachment.add', $since)) === 1, 'bill.draft logs vendor_id, has_document, amount, lines, vendor_ref; attachment.add logged too');
ok((int) one("SELECT count(*) FROM notifications WHERE kind = 'bill_awaiting' AND record_type = 'bill' AND record_id = :b", ['b' => $B1]) >= 1, 'the approvers are told (a bill_awaiting notification)');
$body = page($bea, '/bills/' . $B1)['body'];
ok(!str_contains($body, 'id="bill-head-nodoc"') && str_contains($body, 'id="bill-document-note"') && str_contains($body, 'Attached below.'), 'the page: no "no document" chip');
echo "2. The vendor's reference is unique per vendor\n";
[$c, $b] = act($bea, '/bills/save.php', ['vendor' => $H, 'vendor_ref' => 'h-2026-04', 'lines' => $lines]);
ok($c === 422 && str_contains(msg($b), 'SMOKE Hosting Co\'s h-2026-04 is already entered as ' . $row['number'] . '.') && (int) (fields($b)['record_id'] ?? 0) === $B1, '422 "SMOKE Hosting Co\'s … is already entered as BILL-…" with the bill\'s id as record_id (' . msg($b) . ')');
[$c, $b] = act($bea, '/bills/save.php', ['vendor' => $N, 'vendor_ref' => 'H-2026-04', 'lines' => $lines]);
ok($c === 200, 'the same reference on another vendor is fine');
$B2 = mk_bill($H, [['Second', '1', '10.00']], ['vendor_ref' => 'H-2026-05']);
[$c, $b] = act($bea, '/bills/save.php', ['bill' => $B2, 'vendor_ref' => 'H-2026-04']);
ok($c === 422 && str_contains(msg($b), 'is already entered as'), 'changing a draft\'s reference to a taken one: 422');
echo "3. The lines editor\n";
[$c, $b] = act($bea, '/bills/line-save.php', ['bill' => $B2, 'description' => 'Extra hosting', 'quantity' => '3', 'unit_price' => '4.50']);
$ln = (int) ($b['record_id'] ?? 0);
ok($c === 200 && $ln > 0 && ($b['totals']['total'] ?? '') === '23.50' && (int) one('SELECT expense_account_id FROM bill_lines WHERE id = :l', ['l' => $ln]) === account_id('6200'), 'a line with no account takes the vendor\'s (6200); the totals answer 23.50');
$noV = mk_vendor('SMOKE Plain Vendor'); $B3 = mk_bill($noV, [['Thing', '1', '5.00']], []);
ok((int) one('SELECT expense_account_id FROM bill_lines WHERE bill_id = :b', ['b' => $B3]) === account_id('6200'), 'default account: the line asked 6200 explicitly');
[$c, $b] = act($bea, '/bills/line-save.php', ['bill' => $B3, 'description' => 'No account anywhere', 'quantity' => '1', 'unit_price' => '1']);
ok($c === 200 && (int) one('SELECT expense_account_id FROM bill_lines WHERE id = :l', ['l' => $b['record_id']]) === account_id('6900'), 'no item, no vendor account: 6900 Other expenses');
$item = (int) one("INSERT INTO items (name, unit_price, expense_account_id) VALUES ('SMOKE Domain name', 15.00, :a) RETURNING id", ['a' => account_id('6100')]);
[$c, $b] = act($bea, '/bills/line-save.php', ['bill' => $B3, 'item' => $item, 'quantity' => '2']);
$il = q('SELECT description, unit_price, expense_account_id FROM bill_lines WHERE id = :l', ['l' => $b['record_id']])[0];
ok($c === 200 && $il['description'] === 'SMOKE Domain name' && $il['unit_price'] === '15.0000' && (int) $il['expense_account_id'] === account_id('6100'), 'an item fills description, price and its expense account');
[$c, $b] = act($bea, '/bills/line-save.php', ['bill' => $B3, 'description' => 'Income account', 'quantity' => '1', 'unit_price' => '1', 'expense_account' => account_id('4100')]);
ok($c === 422 && str_contains(msg($b), 'expense account') && (int) (fields($b)['row'] ?? 0) >= 1, 'an income account on a bill line: 422 naming the row (' . msg($b) . ')');
[$c, $b] = act($bea, '/bills/line-save.php', ['bill' => $B3, 'description' => 'Fixed asset', 'quantity' => '1', 'unit_price' => '900', 'expense_account' => account_id('1500')]);
ok($c === 200, 'an asset account is accepted (a prepaid or a fixed asset is bought too)');
[$c, $b] = act($bea, '/bills/line-save.php', ['bill' => $B3, 'description' => 'Four decimals', 'quantity' => '1', 'unit_price' => '0.0125']);
ok($c === 200 && (string) one('SELECT unit_price FROM bill_lines WHERE id = :l', ['l' => $b['record_id']]) === '0.0125', 'a unit price keeps four decimals (the AI statement\'s amounts)');
[$c, $b] = act($bea, '/bills/line-save.php', ['bill' => $B3, 'line' => $ln, 'quantity' => '1']);
ok($c === 404, 'a line of another bill: 404');
[$c, $b] = act($bea, '/bills/line-save.php', ['bill' => $B2, 'line' => $ln, 'quantity' => '4']);
ok($c === 200 && ($b['totals']['total'] ?? '') === '28.00', 'a changed line keeps what was not sent (price 4.50 × 4 = 18.00; the other line 10.00)');
$r = req('POST', '/bills/line-save.php', ['jar' => $bea, 'headers' => ['HX-Request: true', 'HX-Target: bill-lines'], 'form' => ['bill' => $B2, 'description' => 'Htmx', 'quantity' => '1', 'unit_price' => '1', 'csrf_token' => csrf_of(page($bea, '/')['body'])]]);
ok($r['code'] === 200 && str_starts_with(trim($r['body']), '<div id="bill-lines"') && str_contains($r['body'], 'id="bill-totals" hx-swap-oob="true"') && str_contains($r['body'], 'Expense account'), 'under HTMX a line write re-renders #bill-lines with the totals out of band and an Expense account column');
[$c, $b] = act($bea, '/bills/line-remove.php', ['bill' => $B2, 'line' => (int) one('SELECT max(id) FROM bill_lines WHERE bill_id = :b', ['b' => $B2])]);
ok($c === 200 && (string) one('SELECT total FROM bills WHERE id = :b', ['b' => $B2]) === '28.00', 'a line removed: the total follows');
echo "4. The approval\n";
[$c, $b] = act($bea, '/bills/approve.php', ['bill' => $B1]);
ok($c === 403, 'the Bookkeeper approving: 403 (ap.approve is the Controller\'s)');
[$c, $b] = act($vera, '/bills/approve.php', ['bill' => $B1]);
ok($c === 403, 'the Viewer approving: 403');
$since = last_activity_id();
[$c, $b] = act($carl, '/bills/approve.php', ['bill' => $B1]);
ok($c === 200 && ($b['amount'] ?? '') === '359.80' && ($b['has_document'] ?? false) === true && ($b['location'] ?? '') === '/bills/' . $B1 . '?notice=approved', 'bill_approve by the Controller: 200, amount 359.80, has_document true');
$row = bill_row($B1);
ok($row['status'] === 'approved' && (int) $row['approved_by'] === 28 && $row['approved_at'] !== null && $row['journal_entry_id'] !== null && $row['balance_due'] === '359.80', 'approved by 28; posted; 359.80 owed');
$jl = array_column(q('SELECT a.code, l.debit, l.credit, l.vendor_id FROM journal_lines l JOIN accounts a ON a.id = l.account_id WHERE l.entry_id = :e', ['e' => $row['journal_entry_id']]), null, 'code');
ok(count($jl) === 3 && $jl['6200']['debit'] === '259.80' && $jl['6100']['debit'] === '100.00' && $jl['2000']['credit'] === '359.80' && (int) $jl['2000']['vendor_id'] === $H, 'the entry: DR 6200 259.80 (gross, tax included) / DR 6100 100.00 / CR 2000 359.80 against the vendor');
$l = activity('bill.approve', $since)[0]; $a = json_decode((string) $l['after'], true);
ok((int) $l['vendor_id'] === $H && (int) $l['journal_entry_id'] === (int) $row['journal_entry_id'] && $a['number'] === $row['number'] && $a['amount'] === '359.80' && $a['currency'] === 'USD' && str_starts_with($a['journal_entry_number'], 'JE-') && $a['has_document'] === true, 'bill.approve logs vendor_id, journal_entry_id, number, amount, currency, journal_entry_number, has_document true');
[$c, $b] = act($carl, '/bills/approve.php', ['bill' => $B1]);
ok($c === 422 && str_contains(msg($b), 'is already approved'), 'approving twice: 422 in the function\'s words');
[$c, $b] = act($carl, '/bills/approve.php', ['bill' => (int) one('SELECT max(id) FROM bills') + 100]);
ok($c === 404, 'an unknown bill: 404');
$empty = (int) act($bea, '/bills/save.php', ['vendor' => $H, 'lines' => '[]'])[1]['record_id'];
[$c, $b] = act($carl, '/bills/approve.php', ['bill' => $empty]);
ok($c === 422 && str_contains(msg($b), 'A bill needs at least one line'), 'a bill with no line: 422 "A bill needs at least one line"');
echo "5. An approved bill is fixed\n";
[$c, $b] = act($bea, '/bills/line-save.php', ['bill' => $B1, 'description' => 'Sneaky', 'quantity' => '1', 'unit_price' => '1']);
ok($c === 422 && str_contains(msg($b), 'The lines of a bill change only while it is a draft (it is approved)'), 'a line on an approved bill: 422 in the trigger\'s words');
[$c, $b] = act($bea, '/bills/line-remove.php', ['bill' => $B1, 'line' => (int) one('SELECT min(id) FROM bill_lines WHERE bill_id = :b', ['b' => $B1])]);
ok($c === 422, 'removing one: 422');
[$c, $b] = act($bea, '/bills/save.php', ['bill' => $B1, 'bill_date' => '2026-06-02']);
ok($c === 422 && str_contains(msg($b), 'is approved: its vendor, date and totals cannot change'), 'the head: 422 "… is approved: its vendor, date and totals cannot change (credit it, or void it)"');
[$c, $b] = act($bea, '/bills/delete.php', ['bill' => $B1]);
ok($c === 422 && str_contains(msg($b), 'is approved and is never deleted; void it'), 'delete refused: "never deleted; void it"');
ok(req('GET', '/bills/' . $B1 . '/edit', ['jar' => $bea])['code'] === 422, 'the edit form of an approved bill: 422');
$body = page($bea, '/bills/' . $B1)['body'];
ok(!str_contains($body, 'id="bill-lines-table"') === false && !str_contains($body, 'bill-line-new-save-btn') && str_contains($body, 'id="bill-head-entry-link"') && str_contains($body, 'id="bill-void-btn"') === false, 'the page: read-only lines, the entry link; no Void for a Bookkeeper');
$body = page($carl, '/bills/' . $B1)['body'];
ok(str_contains($body, 'id="bill-void-btn"') && str_contains($body, 'id="bill-payment-btn"') && str_contains($body, 'id="bill-copy-btn"'), 'the Controller\'s page: Void, Prepare a payment, Copy');
echo "6. Approved without a document\n";
$B4 = mk_bill($H, [['Paper invoice, scan later', '1', '75.00']], ['vendor_ref' => 'H-NODOC']);
ok((bool) one('SELECT has_attachment FROM mcp_bills WHERE bill_id = :b', ['b' => $B4]) === false, 'a bill with no document: has_attachment false');
$body = page($bea, '/bills/' . $B4)['body'];
ok(str_contains($body, 'id="bill-head-nodoc"') && str_contains($body, 'no document'), 'the draft page wears the no document chip');
$since = last_activity_id();
$body = page($carl, '/bills/' . $B4)['body'];
ok(str_contains($body, 'id="bill-approve-nodoc"') && str_contains($body, 'No document is attached; you can still approve it.'), 'the Controller is told, before approving, that there is no document');
[$c, $b] = act($carl, '/bills/approve.php', ['bill' => $B4]);
ok($c === 200 && ($b['has_document'] ?? true) === false && ($b['location'] ?? '') === '/bills/' . $B4 . '?notice=approved_no_document', 'approval without a document is allowed; the location carries the warning notice');
$a = json_decode((string) activity('bill.approve', $since)[0]['after'], true);
ok($a['has_document'] === false, 'bill.approve logs has_document false');
$body = page($carl, '/bills/' . $B4 . '?notice=approved_no_document')['body'];
ok(str_contains($body, 'but no document is attached to it'), 'the page says so after approving');
[$c, $b] = act_upload($bea, '/attachments/save.php', ['record_type' => 'bill', 'record_id' => $B4], ['file' => [tmp_pdf('SMOKE-late.pdf'), 'scan.pdf']]);
pdo()->exec("SELECT set_config('app.member_id', '27', false)");
ok($c === 200 && (bool) one('SELECT has_attachment FROM mcp_bills WHERE bill_id = :b', ['b' => $B4]) === true, 'attach_later: the chip is gone');
echo "7. Void\n";
[$c, $b] = act($bea, '/bills/void.php', ['bill' => $B4, 'reason' => 'SMOKE']);
ok($c === 403 && msg($b) === 'You may not reverse, void or write off.', 'a Bookkeeper voiding: 403');
[$c, $b] = act($carl, '/bills/void.php', ['bill' => $B4, 'reason' => '']);
ok($c === 422 && str_contains(msg($b), 'Voiding a bill needs a reason'), 'no reason: 422');
$since = last_activity_id();
[$c, $b] = act($carl, '/bills/void.php', ['bill' => $B4, 'reason' => 'SMOKE entered twice']);
$row4 = bill_row($B4);
ok($c === 200 && $row4['status'] === 'void' && $row4['void_reason'] === 'SMOKE entered twice' && (int) one('SELECT count(*) FROM journal_entries WHERE reversal_of = :e', ['e' => $row4['journal_entry_id']]) === 1, 'void: status void, reason kept, the entry reversed');
$l = activity('bill.void', $since)[0]; $a = json_decode((string) $l['after'], true);
ok($a['reason'] === 'SMOKE entered twice' && $a['amount'] === '75.00' && (int) $l['journal_entry_id'] === (int) $row4['journal_entry_id'], 'bill.void logs the reason and amount');
[$c, $b] = act($carl, '/bills/void.php', ['bill' => $B4, 'reason' => 'again']);
ok($c === 422, 'a void bill cannot be voided again');
$B5 = mk_bill($H, [['Same ref after void', '1', '5.00']], ['vendor_ref' => 'H-NODOC']);
ok($B5 > 0, 'a voided bill frees its vendor reference');
echo "8. Copy, delete\n";
$p = page($bea, '/bills/new?copy_of=' . $B1)['body'];
ok(str_contains($p, 'value="Server rental"') && str_contains($p, 'value="Backup"') && str_contains($p, 'id="bill-form-field-vendor"') && preg_match('/name="vendor_ref"[^>]*value=""/', $p) === 1, 'copy_of prefills the vendor and the lines, with no reference');
[$c, $d] = screen($bea, '/bills/new?copy_of=' . $B1);
ok($c === 200 && ($d['copy']['vendor_id'] ?? 0) === $H && count($d['copy']['lines'] ?? []) === 2, 'JSON: the copy prefill');
$since = last_activity_id();
$B6 = mk_bill($H, [['Draft to delete', '1', '9.00']]);
[$c, $b] = act($bea, '/bills/delete.php', ['bill' => $B6]);
ok($c === 200 && one('SELECT 1 FROM bills WHERE id = :b', ['b' => $B6]) === false && count(activity('bill.delete', $since)) === 1, 'bill_delete removes a draft; bill.delete logged');
echo "9. The lists\n";
$body = page($bea, '/bills/')['body'];
ok(str_contains($body, 'id="bills-tab-awaiting"') && str_contains($body, 'id="bills-tab-approved"') && str_contains($body, 'id="bills-tab-due"') && str_contains($body, 'id="bills-tab-all"') && str_contains($body, 'id="bill-row-' . $B1 . '"') && str_contains($body, 'id="bill-card-' . $B1 . '"'), 'tabs awaiting, approved, due, all; a row and a card for the bill');
$d = screen($bea, '/bills/?status=draft')[1];
ok(count($d['bills'] ?? []) >= 2 && array_unique(array_column($d['bills'], 'status')) === ['draft'] && ($d['counts']['awaiting'] ?? 0) >= 2, 'the Awaiting approval tab: drafts only; the tab counts');
$d = screen($bea, '/bills/?status=unpaid')[1];
ok(in_array($B1, array_column($d['bills'], 'bill_id'), true) && !in_array($B4, array_column($d['bills'], 'bill_id'), true), 'the Approved tab: approved and partly paid');
$d = screen($bea, '/bills/?overdue=1&as_of=2026-12-31')[1];
ok(in_array($B1, array_column($d['bills'], 'bill_id'), true) && ($d['bills'][0]['overdue'] ?? null) !== null, 'overdue (as_of): the approved bill due 2026-07-01 is overdue');
$d = screen($bea, '/bills/?overdue=61_90&as_of=2026-09-15')[1];
ok(in_array($B1, array_column($d['bills'], 'bill_id'), true), 'the 61–90 bucket as of 2026-09-15 holds a bill due 2026-07-01 (76 days)');
$d = screen($bea, '/bills/?overdue=1_30&as_of=2026-09-15')[1];
ok(!in_array($B1, array_column($d['bills'], 'bill_id'), true), 'and the 1–30 bucket does not');
$d = screen($bea, '/bills/?due_within=3650')[1];
ok(in_array($B1, array_column($d['bills'], 'bill_id'), true) && array_unique(array_column($d['bills'], 'status')) <= ['approved', 'partially_paid'], 'due_within lists open bills due by then');
$B7 = ready_bill($H, [['No doc', '1', '11.00']], ['vendor_ref' => 'H-NODOC-2']);
$d = screen($bea, '/bills/?no_document=1')[1];
ok(in_array($B7, array_column($d['bills'], 'bill_id'), true) && !in_array($B1, array_column($d['bills'], 'bill_id'), true) && !in_array($B4, array_column($d['bills'], 'bill_id'), true), 'no_document lists bills with none (not the documented, not the void)');
$d = screen($bea, '/bills/?q=H-2026-04')[1];
ok(count($d['bills']) >= 1 && in_array($B1, array_column($d['bills'], 'bill_id'), true), 'q finds a vendor reference');
$d = screen($bea, '/bills/?vendor=' . $N)[1];
ok(array_unique(array_column($d['bills'], 'vendor')) !== [] && count(array_filter($d['bills'], fn ($x) => $x['vendor']['vendor_id'] !== $N)) === 0, 'vendor filters');
$d = screen($bea, '/bills/?status=approved')[1];
ok(($d['totals'][0]['currency'] ?? '') === 'USD' && m_cmp((string) $d['totals'][0]['total'], '0') > 0, 'the totals footer per currency');
$r = req('GET', '/bills/', ['jar' => $bea, 'headers' => ['HX-Request: true', 'HX-Target: bill-list']]);
ok(str_starts_with(trim($r['body']), '<div id="bill-list"') && str_contains($r['body'], 'hx-trigger="billChanged from:body"'), 'the filter swaps #bill-list, which listens to billChanged');
$since = last_activity_id();
$r = req('GET', '/bills/?format=csv', ['jar' => $carl]);
ok($r['code'] === 200 && str_contains($r['headers'], 'text/csv') && str_starts_with($r['body'], 'number,vendor,their_reference') && count(activity('export.download', $since)) === 1, 'CSV for the Controller (exports.download), logged export.download');
ok(req('GET', '/bills/?format=csv', ['jar' => $bea])['code'] === 403, 'CSV for the Bookkeeper: 403');
$body = page($vera, '/bills/' . $B1)['body'];
ok(!str_contains($body, 'id="bill-actions"') && !str_contains($body, 'id="bill-approve-btn"'), 'a Viewer sees the bill without actions');
finish();
